  const profile=async cid=>{const c=await get('customers',cid),[sales,pays]=await Promise.all([R.query('sales',{customerId:cid,page:1,size:10,sort:'at',dir:'desc'}),R.query('customerPayments',{customerId:cid,page:1,size:10,sort:'at',dir:'desc'})]);modal(`Customer 360 — ${c.name}`,`<div class="detail-grid"><div class="detail-box"><small>الهاتف</small><b>${esc(c.phone||'—')}</b></div><div class="detail-box"><small>المديونية</small><b>${money(c.balance)}</b></div><div class="detail-box"><small>حد الائتمان</small><b>${money(c.creditLimit)}</b></div><div class="detail-box"><small>الرصيد الدائن</small><b>${money(c.creditBalance)}</b></div></div>${c.allergies?`<div class="notice warn section-gap-sm">حساسية مسجلة: ${esc(c.allergies)}</div>`:''}<div class="notice info section-gap-sm">ملف 360 يجمع الرصيد والحركة الأخيرة والتحصيلات في شاشة واحدة.</div><div class="notice info section-gap-sm">ملف 360 يجمع المستحقات والمشتريات والمدفوعات في شاشة واحدة.</div><div class="grid two section-gap"><div><h3>آخر المشتريات</h3><div class="list">${sales.items.map(s=>`<div class="list-item"><div><b>${esc(s.no)}</b><small>${A.fmtDT(s.at)}</small></div><b>${money(s.total)}</b></div>`).join('')||empty()}</div></div><div><h3>آخر التحصيلات</h3><div class="list">${pays.items.map(p=>`<div class="list-item"><div><b>${A.fmtDT(p.at)}</b><small>${esc(payName(p.method))}</small></div><b>${money(p.amount)}</b></div>`).join('')||empty()}</div></div></div>`,`<button class="btn" data-close>إغلاق</button><button id="srvEditCust" class="btn primary">تعديل</button>`);$('#srvEditCust').onclick=()=>openForm(cid)};
  const load=async()=>{const r=await R.query('customers',{...st,sort:'name',dir:'asc'}),root=$('#srvCustomers');root.innerHTML=`<div class="list">${r.items.map(c=>`<div class="list-item"><div><b>${esc(c.name)}</b><small>${esc(c.phone||'')} ${c.address?`• ${esc(c.address)}`:''}</small></div><div class="row-actions"><span class="customer-balance-wrap"><strong class="${num(c.balance)>0?'text-danger':''}">${money(c.balance)}</strong>${num(c.balance)<=0?badge('سليم','ok'):num(c.creditLimit)>0&&num(c.balance)>=num(c.creditLimit)?badge('بلغ الحد','danger'):badge('مديون','warn')}</span><button class="btn tiny" data-cp="${c.id}">الملف</button>${num(c.balance)>0?`<button class="btn tiny primary" data-cc="${c.id}">تحصيل</button>`:''}</div></div>`).join('')||empty('لا يوجد عملاء')}</div>${pager(r,'عميل')}`;bindPager(root,st,r,load);root.querySelectorAll('[data-cp]').forEach(b=>b.onclick=()=>profile(b.dataset.cp));root.querySelectorAll('[data-cc]').forEach(b=>b.onclick=()=>collect(b.dataset.cc))};$('#srvNewCustomer').onclick=()=>openForm();$('#srvCustQ').oninput=debounce(()=>{st.q=$('#srvCustQ').value.trim();st.page=1;load()});await load();
