  const profile=async sid=>{const s=await get('suppliers',sid),[purs,pays]=await Promise.all([R.query('purchases',{supplierId:sid,page:1,size:10,sort:'at',dir:'desc'}),R.query('supplierPayments',{supplierId:sid,page:1,size:10,sort:'at',dir:'desc'})]);modal(`Supplier 360 — ${s.name}`,`<div class="detail-grid"><div class="detail-box"><small>المستحق</small><b>${money(s.balance)}</b></div><div class="detail-box"><small>رصيد لصالحنا</small><b>${money(s.creditBalance)}</b></div><div class="detail-box"><small>حد الائتمان</small><b>${money(s.creditLimit)}</b></div><div class="detail-box"><small>أجل السداد</small><b>${num(s.paymentTermsDays)} يوم</b></div></div><div class="grid two section-gap"><div><h3>آخر المشتريات</h3><div class="list">${purs.items.map(p=>`<div class="list-item"><div><b>${esc(p.no)}</b><small>${A.fmtDate(p.invoiceDate||p.at)}</small></div><b>${money(p.total)}</b></div>`).join('')||empty()}</div></div><div><h3>آخر المدفوعات</h3><div class="list">${pays.items.map(p=>`<div class="list-item"><div><b>${A.fmtDate(p.at)}</b><small>${esc(payName(p.method))}</small></div><b>${money(p.amount)}</b></div>`).join('')||empty()}</div></div></div>`,`<button class="btn" data-close>إغلاق</button><button id="srvEditSup" class="btn primary">تعديل</button>`);$('#srvEditSup').onclick=()=>edit(sid)};
